#include <system_error>
#include <iostream>

int main() {
    const std::error_category& cat1 = std::generic_category();  // Obtains a reference to the singleton instance
    const std::error_category& cat2 = std::generic_category();  // Another reference to the same singleton
    bool equal = (cat1 == cat2);  // Invokes operator==, which compares pointers
    std::cout << std::boolalpha << equal << std::endl;  // Outputs: true
    return 0;
}
